#include <cstdio>
#include <vector>
#include <deque>

int main() {
    int n, k;
    scanf("%d %d", &n, &k);
    std::vector<long long> a(n);
    for (int i = 0; i < n; ++i) scanf("%lld", &a[i]);

    std::deque<int> dq;
    bool first = true;
    for (int i = 0; i < n; ++i) {
        while (!dq.empty() && a[dq.back()] <= a[i]) dq.pop_back();
        dq.push_back(i);
        if (dq.front() <= i - k) dq.pop_front();
        if (i >= k - 1) {
            if (!first) printf(" ");
            printf("%lld", a[dq.front()]);
            first = false;
        }
    }
    printf("\n");
    return 0;
}
